#include <iostream>
using namespace std;

int main() {
    int n;
    cin>>n;
    int nums = 0;
    cin >> nums;
    int max = nums;
    for(int i=1; i<n; i++) {
    	cin >> nums;
    	
        if( nums > max){
            max = nums;
        }
       
    }
    cout << max << endl;

    return 0;
}
